\begin{abstract}
    Drifts of asset returns are notoriously difficult to model accurately and, yet, trading strategies obtained from portfolio optimization are very sensitive to them. To mitigate this well-known phenomenon we study robust growth-optimization in a high-dimensional incomplete market under drift uncertainty of the asset price process $X$, under an additional ergodicity assumption, which constrains but does not fully specify the drift in general. The class of admissible models allows $X$ to depend on a multivariate stochastic factor $Y$ and fixes (a) their joint volatility structure, (b) their long-term joint ergodic density and (c) the dynamics of the stochastic factor process $Y$. A principal motivation of this framework comes from pairs trading, where $X$ is the spread process and models with the above characteristics are commonplace. Our main results determine the robust optimal growth rate, construct a worst-case admissible model and characterize the robust growth-optimal strategy via a solution to a certain partial differential equation (PDE). We demonstrate that utilizing the stochastic factor leads to improvement in robust growth complementing the conclusions of the previous study \cite{itkin2025ergodic}, which additionally robustified the dynamics of the stochastic factor leading to $Y$-independent optimal strategies. Our analysis leads to new financial insights, quantifying the improvement in growth the investor can achieve by optimally incorporating stochastic factors into their trading decisions. We illustrate our theoretical results on several numerical examples including an application to pairs trading. 
\end{abstract}


\paragraph*{Keywords:} Robust finance, Growth maximization, Pairs trading, Statistical arbitrage, Stochastic factors, Calculus of variations, Ergodic process


\paragraph*{MSC 2020 Classification:} 91G10, 60G10, 60J46

\label{sec:problem_formulation}
We work with a financial market that contains a risk-free numeraire asset, which is normalized to one, and $d \geq 1$ risky assets. Notice that the numeraire of our investment universe is chosen in such a way that ergodicity assumptions can reasonably hold true. We assume that the risky asset price process $X = (X_1,\dots,X_d)$ takes values in an open connected set $E \subset \R^d$. The process $X$ will depend on an $m$-dimensional stochastic factor process $Y$ taking values in a connected open set $D \subset \R^m$ for some $m \geq 1$. We set $F = E \times D$ and in this paper will generically denote elements of $F$  by $z = (x,y)$ for $x \in E$ and $y \in D$. Similarly, gradients of a function of $z$ taken in only the $x$-variable will be denoted by $\nabla_x$ and in only the $y$-variable by $\nabla_y$ and the full gradient denoted, as usual, by $\nabla$. For a vector $v$ of size $d+m$, we will write $v_X$ and $v_Y$ for the vector consisting of the first $d$ and final $m$ components of $v$ respectively.

We take a triple $(c,p,b_Y)$ as inputs to the problem for functions $c:F \to \mathbb{S}^{d+m}_{++}$, $p:F\to (0,\infty)$ and $b_Y:F \to \R^m$. Here, for any $n \in \N$, $\mathbb{S}^{n}_{++}$ is the cone of symmetric positive definite matrices of size $n \times n$. We will canonically write $c$ in block form as \[c(z) = \begin{bmatrix}
    c_X(z) & c_{XY}(z) \\ c_{YX}(z) & c_Y(z)
\end{bmatrix},\] where $c_X(z) \in \mathbb{S}^{d}_{++}$, $c_Y(z) \in \mathbb{S}^m_{++}$ and $c_{XY}(z) = c_{YX}^\top (z)$ is a matrix of size $d \times m$. We make the following assumptions on the regularity of the inputs. 

\begin{assum}
\label{ass:inputs}
There exists $\gamma \in (0,1]$ such that 
\begin{enumerate}[noitemsep] 
\item $c \in C^{2,\gamma}(F;\mathbb{S}^{d+m}_{++})$,
\item $p \in C^{2,\gamma}(F;(0,\infty))$ is such that $\int_F p(z)dz = 1$,
\item $b_Y \in C^{1,\gamma}(F;\R^m)$.





\end{enumerate}


\end{assum} 




Regarding the probabilistic structure, we will work on the canonical path space $\Omega = C([0,\infty);F)$ with Borel $\sigma$-algebra induced by the topology of local uniform convergence. The coordinate process is denoted by $Z = (X,Y)$ and we let $(\Fcal_t)_{t \geq 0}$ by the right-continuous enlargement of the filtration generated by $Z$ modelling full information on $(X,Y)$. On this space we will consider a class of probability measures under which $Z$ has quadratic variation prescribed by $c$, ergodic behaviour prescribed by $p$ and the drift of the $Y$-component of $Z$ is given in terms of $b_Y$.
\begin{defn}[Admissible class of measures] \label{defn:class} Given inputs $(c,p,b_Y)$ satisfying Assumption~\ref{ass:inputs}, we define a class of probability measures $\Pcal$ on $(\Omega,\F)$ consisting of all measures $\P$ under which
\begin{enumerate}
    \item \label{item:dynamics} $Z$ is a continuous semimartingale with dynamics 
    \begin{equation} \label{eqn:Z_dynamics} 
    dZ_t  = dA_t^\P + c^{1/2}(Z_t)dW_t,
    \end{equation}
    where $W$ is a standard $(d+m)$-dimensional Brownian motion, $c^{1/2}(z)$ is a matrix square root of $c(z)$ and $A^\P$ is a finite variation process of the form
    \begin{equation} \label{eqn:dA}
        dA_t^\P = \begin{pmatrix} dA^\P_{X,t} \\ c_Y(Z_t)b_Y(Z_t)dt \end{pmatrix},
    \end{equation}
    where $A^\P_X$ is some continuous adapted $d$-dimensional process of finite variation,
    \item $Z$ satisfies the ergodic property,
    \begin{equation} \label{eqn:ergodic}
    \lim_{T \to \infty} \frac{1}{T}\int_0^T h(Z_t)dt = \int_F h(z)p(z)dz; \qquad \P\text{-a.s.,}
    \end{equation}
    for every locally bounded $h:F \to \R$ with $\int_F h(z)p(z)dz < \infty$. \label{item:ergodic}

\end{enumerate}
\end{defn}

As in \cite{kardaras2021ergodic} and \cite[Section~5]{itkin2025ergodic}, the diffusion matrix of the coordinate process is specified by the matrix $c$ and the density $p$ governs the long-term behaviour of the coordinate process. However, differently from \cite{kardaras2021ergodic} the market is incomplete and, differently from \cite{itkin2025ergodic}, we assume that the local dynamics of the stochastic factor process are entirely known. Indeed, the drift of $Y$ is specified by the input $b_Y$, which was not present in previous studies.\footnote{The parametrization $c_Y(z)b_Y(z)$ for the drift of $Y$ in \eqref{eqn:dA} is convenient for later computations, but does not amount to any additional structural condition on the drift of $Y$ since $c_Y$ is everywhere invertible.} Accordingly, the class $\Pcal$ is a subset of the class considered in \cite{itkin2025ergodic}, which did not restrict the drift coefficients of $Y$.\footnote{The paper \cite{itkin2025ergodic} introduced a family of classes $\Pi_K$ for so-called \emph{$K$-modifications}. These are not needed in this paper and, hence, for simplicity we drop the subscript $K$ when comparing to the classes from \cite[Section~5.2]{itkin2025ergodic}.}
As such, the class $\Pcal$ provides uncertainty over only the drift of $X$, while the classes of measures in \cite{itkin2025ergodic} additionally encoded uncertainty over the drift of $Y$.



With the class of measures fixed, we now turn our attention to the optimal investment criterion. The set of admissible strategies is denoted by $\Theta$ and consists of all predictable $d$-dimensional processes $(\theta_t)_{t \geq 0}$ modelling full information on $(X,Y)$, which are additionally $X$-integrable with respect to every measure $\P \in \Pcal$. 

When the investor uses a strategy $\theta \in \Theta$ their wealth process is given by
\begin{equation} \label{eqn:wealth} 
V_T^\theta = \Ecal\bigg(\int_0^T \theta_t^\top dX_t\bigg), \qquad T \geq 0,
\end{equation}
where $\Ecal$ denotes stochastic exponentiation and we assume without loss of generality that the initial wealth is normalized to $V_0^\theta = 1$.


We consider the asymptotic growth rate as the optimality criterion. For $\theta \in \Theta$ and $\P \in \Pcal$ this quantity is defined as 
\begin{equation}\label{eqn:growth_rate}

    g(\theta;\P) = \sup\left\{\gamma \in \R: \liminf_{T \to \infty} \frac{1}{T}\log V_T^\theta \geq \gamma; \quad \P\text{-a.s.}\right\}
\end{equation}



The corresponding robust growth rate is then given by \eqref{eqn:lambda_P}.
Our ambitious goal in the sequel is to characterize the growth rate $\lambda_\Pcal$ in terms of the inputs, find the optimal strategy $\theta^*$ achieving it and compare the robust optimal growth rate and strategy to the one previously obtained in \cite{itkin2025ergodic}. It is remarkable how explicit the results are.

\begin{remark} \label{rem:growth_rate}
The pathwise growth rate definition \eqref{eqn:growth_rate} was previously studied in  \cite{kardrarasrobust2012} and \cite[Section~2.3.7]{karatzas2021portfolio}, but differs from the in-probability definition
\begin{equation} \label{eqn:growth_rate_prob}
g_{\mathrm{prob}}(\theta;\P) = \sup\Big\{\gamma \in \R: \lim_{T \to \infty} \P\Big(\frac{1}{T}\log V_T^\theta \geq \gamma\Big) = 1\Big\}
\end{equation}
used in \cite{kardaras2021ergodic,itkin2025ergodic}. Our approach below allows us to characterize the robust growth rate when using the definition \eqref{eqn:growth_rate} and since $g(\theta;\P) \leq g_{\mathrm{prob}}(\theta;\P)$ we prefer to use it here as it is a more conservative choice. However, our results carry over to the in-probability notion of growth rate as well. Moreover, the results of \cite{kardaras2021ergodic,itkin2025ergodic} can be extended to the growth-rate definition \eqref{eqn:growth_rate} when restricting the admissible class of measures in those papers to those with finite asymptotic growth; see Definition~\ref{defn:P0} below for this condition and the proof of Theorem~\ref{thm:main} in Appendix~\ref{sec:proof_main} for how the finite asymptotic growth condition is used.
\end{remark}

Before proceeding, we note that the inputs $(c,p,b_Y)$ cannot be entirely independently specified. Indeed, they need to satisfy a compatibility condition so that the class $\Pcal$ is nonempty. We now formally derive this condition. To begin with, we define the quantities
\begin{align} 
    \ell_X(z) & = \frac{1}{2}\Big(\!(c^{-1}\mathrm{div} \, c)_X(z) + \nabla_x \log p(z) + (c_X)^{-1}(z)c_{XY}(z)\big((c^{-1}\mathrm{div} \, c)_Y(z) + \nabla_y \log p(z)\big)\!\Big), \label{eqn:ell_X}\\
    \ell_Y(z) & = \frac{1}{2}\Big(\!(c^{-1}\mathrm{div} \, c)_Y(z) + \nabla_y \log p(z) + (c_Y)^{-1}(z)c_{YX}(z)\big((c^{-1}\mathrm{div} \, c)_X(z) + \nabla_x \log p(z)\big)\!\Big)\! - b_Y(z), \label{eqn:ell_Y} 
\end{align}
which play an important role here and in the sequel. Here, $\mathrm{div} \, c(z)$ is a vector obtained by computing the row-wise divergence of $c$; that is  $\mathrm{div} \, c_i(z) = \sum_{j=1}^{d+m} \partial_j c_{ij}(z)$. Next, assume that a measure $\P \in \Pcal$ is given and let $\phi \in C_c^\infty(D)$ be arbitrary. Then using It\^o's formula we have that
\[\phi(Y_T) = \phi(Y_0) +  M_T + \int_0^T \big(\nabla \phi(Y_t)^\top c_Y(Z_t) b_Y(Z_t)  + \frac{1}{2}\sum_{i,j=1}^m \partial_{ij}\phi(Y_t)(c_Y)_{ij}(Z_t)\big)dt , \]
where 
    $M_T = \int_0^T\sum_{i=1}^m\sum_{j=1}^{d+m} \partial_i \phi(Y_t)c^{1/2}_{d+i,j}(Z_t)dW_{j,t}$ is a local martingale.
We now divide both sides by $T$ and send $T \to \infty$ to deduce that
\[0 = \int_E\int_D \big(\nabla \phi(y)^\top c_Y(x,y)b_Y(x,y) + \frac{1}{2}\mathrm{Tr}(\nabla^2 \phi(y)c_Y(x,y))\big)p(x,y)dydx. \]
Here we used the fact that $\phi$ is bounded, $M_T/T \to 0$ almost surely (see e.g.\ \cite[Lemma~1.3.2]{fernholz2002stochastic}) and the ergodic property \eqref{eqn:ergodic}. Integrating by parts the first term once and the second term twice yields
\[0 = \int_D \phi(y)\int_E \mathrm{div}_y(c_Y(x,y)\ell_Y(x,y)p(x,y))dx dy,\]
where we also switched the order of integration. Since $\phi$ was arbitrary, we have derived, by density of $C_c^\infty(D)$ in $L^1_{\mathrm{loc}}(D)$, the following compatibility condition connecting the inputs $(c,p,b_Y)$,
\begin{equation} \label{eqn:compatibility_condition}
    \int_E \mathrm{div}_y(c_Y(x,y)\ell_Y(x,y)p(x,y))dx = 0 \qquad \text{for  a.e. } y \in D.
\end{equation}
If one fixes the inputs $c$ and $p$ then one explicit way to ensure that $\eqref{eqn:compatibility_condition}$ holds it to  set
\begin{equation} \label{eqn:explicit_compatability}
    b_Y(z) = \frac{1}{2}\Big((c^{-1}\mathrm{div} \, c)_Y(z) + \nabla_y \log p(z) +(c_Y)^{-1}(z)c_{YX}(z)\big((c^{-1}\mathrm{div}\, c)_X(z) + \nabla_x \log p(z)\big)\Big),
\end{equation}
in which case $\ell_Y(z) = 0$ for all $z \in F$. In the examples of Section~\ref{sec:examples} we will specify inputs $(c,p,b_Y)$ that satisfy the compatibility condition \eqref{eqn:compatibility_condition} without imposing $\ell_Y = 0$.

\label{sec:heuristic}
The problem \eqref{eqn:lambda_P} is not easily amenable to standard tools from stochastic control. The main difficulty stems from the infinite horizon together with the ergodic constraint \eqref{eqn:ergodic}. Mathematically, the ergodic condition can be thought of as a constraint on the limit as $t \to \infty$ of the marginal distribution of $Z_t$, but it does not offer a more direct restriction of $b_{t,X}^{\P}$. In particular, as it is an infinite-horizon constraint and, so is the criterion \eqref{eqn:growth_rate}, approaches using possibly existing dominated measures for the class $\Pcal$ may be technically challenging.

Instead, we follow a similar approach to \cite{kardaras2021ergodic,itkin2025ergodic} by first restricting our analysis to a suitable class $\Theta_0 \subset \Theta$ of trading strategies that achieve the same growth rate under each admissible measure. Afterwards, we will establish that the robust  optimal strategy over this smaller class is actually globally robust growth-optimal. Here, we take the class

\[\Theta_0  =\{\theta \in \Theta: \theta_t = \nabla_x \phi(X_t,Y_t) \text{ for some } \phi \in C^2_c(F)\}. \]
This is a natural extension of the class
$\{\theta \in \Theta: \theta_t = \nabla \phi(X_t) \text{ for some } \phi \in C^2_c(E)\}$  of functionally generated portfolios considered in \cite{kardaras2021ergodic,itkin2025ergodic} to allow dependence on $Y$, for which more information is available in this setting due to the input $b_Y$. In essence, the portfolios making up $\Theta_0$ can be thought of as stochastic factor dependent functionally generated portfolios and, in this setting, they are needed to obtain robust optimality. From \eqref{eqn:wealth} and It\^o's formula applied to $\phi(Z_t)$ it follows that the logarithmic wealth when using a strategy $\theta^\phi_t := \nabla_x \phi(Z_t) \in \Theta_0$ is
\begin{align}
    \log V_T^{\theta^\phi} & =  \int_0^T \nabla_x \phi(Z_t)^\top dX_t - \frac{1}{2}\int_0^T \nabla_x \phi(Z_t)^\top d[X]_t \nabla_x \phi(Z_t) \\
    & = \phi(Z_T) - \phi(Z_0) - \int_0^T \nabla_y \phi(Z_t)^\top dY_t - \frac{1}{2}\sum_{i,j=1}^{d+m}\int_0^T  \partial_{ij} \phi(Z_t) d[Z_i,Z_j]_t \\
    & \qquad \qquad \qquad \qquad \quad - \frac{1}{2}\int_0^T \nabla_x \phi(Z_t)^\top d[X]_t \nabla_x \phi(Z_t).
\end{align}
Using \ref{defn:class}\ref{item:dynamics} we obtain for every $\P \in \Pcal$ the relationship
\begin{align} \label{eqn:heuristic_wealth1} \log & V_T^{\theta^\phi}  =  \phi(Z_T) - \phi(Z_0) - M_T  \\
& \label{eqn:heuristic_wealth2}  - \int_0^T \big(\nabla_y \phi(Z_t)^\top c_Y(Z_t) b_Y(Z_t) + \frac{1}{2}\mathrm{Tr}(\nabla^2 \phi (Z_t)c(Z_t)) + \frac{1}{2}\nabla_x \phi(Z_t)^\top c_X(Z_t)\nabla_x \phi(Z_t)\big)dt, 
\end{align}
where $M_T = \int_0^T \sum_{i=1}^m\sum_{j=1}^{d+m} \partial_i \phi(Z_t)c_{d+i,j}^{1/2}(Z_t)dW_{j,t}$ is a local martingale. Dividing both sides by $T$ and sending $T \to \infty$, we see by boundedness of $\phi$, and \cite[Lemma~1.3.2]{fernholz2002stochastic} for the local martingale part, that the terms on the right hand side of \eqref{eqn:heuristic_wealth1} vanish. By the ergodic property of Definition~\ref{defn:class}\ref{item:ergodic} the terms in \eqref{eqn:heuristic_wealth2} converge leading to
\[g(\theta^\phi;\P) = -\int_F\big(\nabla_y \phi(z)^\top c_Y(z) b_Y(z) + \frac{1}{2}\mathrm{Tr}(\nabla^2 \phi (z)c(z)) + \frac{1}{2}\nabla_x \phi(z)^\top c_X(z)\nabla_x \phi(z)\big)p(z)dz. \]
Importantly, the right hand side depends on the measure $\P$ \emph{only via $(c,p,b_Y)$}. To make further progress we integrate by parts the second derivative terms. Separately collecting all of the terms involving $\nabla_x \phi$ and $\nabla_y \phi$ allows us to rewrite the asymptotic growth rate as 
\begin{equation}
\begin{aligned}
    g(\theta^\phi;\P) & = \int_F \nabla_x \phi(z)^\top c_X(z) \ell_X(z)p(z)dz - \frac{1}{2}\int_F \nabla_x \phi(z)^\top c_X(z)\nabla_x \phi(z)p(z)dz  \\
    & \qquad + \int_F \nabla_y \phi(z)^\top c_Y(z)\ell_Y(z)p(z)dz, \label{eqn:growth_rate_IBP} 
\end{aligned}
\end{equation}
where we recall that $\ell_X,\ell_Y$ are given by \eqref{eqn:ell_X} and \eqref{eqn:ell_Y}, respectively.

We now seek to put the expression \eqref{eqn:growth_rate_IBP} into a more regular form involving only $\nabla_x \phi$, but not $\nabla_y \phi$ or $\phi$ itself. To accomplish this we further integrate by parts the final term in \eqref{eqn:growth_rate_IBP} to obtain
\begin{equation} \label{eqn:IBP_y}
    \int_F \nabla_y \phi(z)^\top c_Y(z)\ell_Y(z)p(z)dz = -\int_F \phi(z)\mathrm{div}_y(c_Y(z)\ell_Y(z) p(z))dz.
\end{equation}

 Next, we seek to construct a vector field $\mathbf{u}:F \to \R^d$ satisfying
\begin{equation} \label{eqn:div_PDE}
    \mathrm{div}_x \mathbf{u}(\cdot,y) = \mathrm{div}_y(c_Y(\cdot,y)\ell_Y(\cdot,y) p(\cdot,y)), \qquad \text{in } E \text{ for a.e. } y \in D
\end{equation}

together with certain integrability bounds precisely stated in Assumption~\ref{ass:conditions}\ref{item:divergence} of the following section. Once such a $\mathbf{u}$ is found we substitute into \eqref{eqn:IBP_y} and integrate by parts again to obtain
\[\int_F \nabla_y \phi(z)^\top c_Y(z)\ell_Y(z)p(z)dz = \int_F \nabla_x \phi(z)^\top \mathbf{u}(z)dz.\]
Substituting into \eqref{eqn:growth_rate_IBP} gives
\begin{align}
    g(\theta^\phi;\P)&  = \int_F (\xi(z)^\top c_X(z)\nabla_x \phi(z)- \frac{1}{2}\nabla_x \phi(z)^\top c_X(z)\nabla_x \phi(z))p(z)dz \\
    & = \frac{1}{2}\int_F \xi(z)^\top c_X(z)\xi(z)p(z)dz - \frac{1}{2}\int_F (\nabla_x \phi(z) - \xi(z))^\top c_X(z)(\nabla_x \phi(z) - \xi(z))p(z)dz, 
\end{align}
where 
\begin{equation} \label{eqn:xi}
\xi(z) = \ell_X(z) + (c_X)^{-1}(z)\mathbf{u}(z)p^{-1}(z).
\end{equation}
Maximizing the  robust asymptotic growth rate over $\Theta_0$ now amounts to minimizing the functional
\[\phi \mapsto \frac{1}{2}\int_F (\nabla_x \phi(z) - \xi(z))^\top c_X(z)(\nabla_x \phi(z) - \xi(z))p(z)dz \]
over a suitable function space. Under certain assumptions on the inputs (see Assumption~\ref{ass:conditions}) a sufficiently regular solution $\phi^*$ can be found and it satisfies the associated Euler--Lagrange equation 
\begin{align}
    \label{eqn:Euler-Lagrange_xi} 
 & \mathrm{div}_x(c_X(\cdot,y)(\nabla_x \phi^*(\cdot,y) - \xi(\cdot,y))p(\cdot,y))  =0 &   \text{in $E$ for a.e.\ $y \in D$}. \end{align}

This now leads us to a lower bound for $\lambda_\Pcal$ since
\begin{equation} \label{eqn:lower_bound}
\begin{aligned}
\lambda_\Pcal \geq \sup_{\theta^\phi \in \Theta_0}\inf_{\P \in \Pcal} g(\theta^\phi;\P) & = \frac{1}{2}\int_F \xi(z)^\top c_X(z)\xi(z)p(z)dz \\
& \qquad - \frac{1}{2}\int_F (\nabla_x \phi^*(z) - \xi(z))^\top c_X(z)(\nabla_x \phi^*(z) - \xi(z))p(z)dz \\


    & = \frac{1}{2}\int_F\nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z) p(z)dz, 
\end{aligned}
\end{equation}
where to obtain the final equality we expanded the quadratic form and used the Euler--Lagrange equation \eqref{eqn:Euler-Lagrange_xi} to formally rewrite the cross term 
\begin{align}
    \int_F \nabla_x \phi^*(z)^\top c_X(z) &\xi(z)p(z)dz  = -\int_F \phi^*(z)\mathrm{div}_x(c_X(z)\xi(z) p(z))dz \\
    & = -\int_F \phi^*(z)\mathrm{div}_x(c_X(z)\nabla_x \phi^*(z) p(z))dz  = \int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz.
\end{align}
To close the gap and obtain the same upper bound we will construct a worst-case measure $\P^* \in \Pcal$ under which $\theta^* := \theta^{\phi^*}$ is growth-optimal. The key observation, first noted in \cite{kardaras2021ergodic} for their problem but continues to hold in this more general setting, is that the stationary Fokker--Planck equation corresponding to the stochastic differential equation (SDE) as in \eqref{eqn:Z_dynamics} with $ d A_{X,t}^{\P^*} = b_{X,t}^{\P^*} dt = c_X(Z_t)\nabla_x \phi^*(Z_t) dt$ is precisely the Euler--Lagrange equation \eqref{eqn:Euler-Lagrange_xi}. This suggests, formally, that $p$ is the invariant density for $Z$ and, hence, that $\P^* \in \Pcal$. Moreover, under $\P^*$, it is easily verified from the general theory of growth-optimal portfolios (see \cite[Theorem~2.31]{karatzas2021portfolio}) that the growth-optimal strategy is given by $\theta^*$ and its asymptotic growth rate under $\P^*$ is equal to the right hand side of \eqref{eqn:lower_bound}. It follows that
\begin{equation} \label{eqn:upper_bound}
\lambda_\Pcal \leq \sup_{\theta \in \Theta} g(\theta;\P^*) = g( \theta^*;\P^*) = \frac{1}{2}\int_F \nabla_x \phi^*(z)c_X(z)\nabla_x\phi^*(z)p(z)dz.
\end{equation}
The bounds \eqref{eqn:lower_bound} and \eqref{eqn:upper_bound} imply that $\lambda_\Pcal = \frac{1}{2}\int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz$ and suggest that the robust growth-optimal portfolio is given by $\theta^*=\nabla_x \phi^*(Z)$.

\begin{remark}
Notice that our robust optimal growth problem under ergodicity, as well as the problems in \cite{kardaras2021ergodic} and \cite{itkin2025ergodic}, allow for a finite horizon formulation, when the market is assumed to start in the invariant law and the optimization is averaging over this initial measure. Of course the setup has to be formulated slightly differently to guarantee preservation of the respective invariant measure, but the results remain valid.
\end{remark}

The discussion in the previous section was heuristic and requires additional assumptions on the inputs to make the argument rigorous. We now state these assumptions. 













\begin{assum} \label{ass:conditions}
    Let inputs $(c,p,b_Y)$ satisfying Assumption~\ref{ass:inputs} be given and let $\ell_X,\ell_Y$ be as defined in \eqref{eqn:ell_X} and \eqref{eqn:ell_Y}. Assume additionally that the following hold:
    \begin{enumerate}
        \item $\int_F \ell_X(z)^\top c_X(z)\ell_X(z)p(z)dz + \int_F \ell_Y(z)^\top c_Y(z)\ell_Y(z)p(z)dz < \infty$, \label{item:finite_growth}
        \item There exists a measurable  ${\bf u}:F\to \R^d$ which satisfies $\int_F \mathbf{u}(z)^\top (c_X)^{-1}(z)\mathbf{u}(z)p^{-1}(z)dz < \infty$ and is a weak solution to \eqref{eqn:div_PDE}. That is,
        \[-\int_E \mathbf{u}(x,y)\nabla \psi(x)dx = \int_E \mathrm{div}_y(c_Y(x,y)\ell_Y(x,y)p(x,y))\psi(x)dx\]
     for all $\psi \in C_c^\infty(E)$ and for a.e.\ $y \in D$.
 \label{item:divergence} 

        \item \label{item:test_functions}
        There exist functions $\chi_n \in C_c^\infty(F)$ satisfying $0 \leq \chi_n \leq 1$, $\lim_{n \to \infty} \chi_n = 1$ and 
        \[\lim_{n \to \infty} \int_F \nabla_x\chi_n(z)^\top c_X(z)\nabla_x\chi_n(z)p(z)dz  = \lim_{n \to \infty} \int_F \nabla_y \chi_n(z)^\top c_Y(z)\nabla_y \chi_n(z)p(z)dz = 0. \] 

    \end{enumerate}
\end{assum}
\begin{remark} \label{rem:u}
    We remark that the compatibility condition \eqref{eqn:compatibility_condition} is not \emph{explicitly} assumed. However, we cannot expect Assumption~\ref{ass:conditions}\ref{item:divergence} to hold without it. This is most easily seen in the case that $d=1$, $E = \R$ and $c_X$ is bounded. In this case the unique (up to additive function of $y$) solution to \eqref{eqn:div_PDE} is \begin{equation} \label{eqn:u_d=1}
        \mathbf{u}(x,y) = \int_{-\infty}^x \mathrm{div}_y(c_Y(x',y)\ell_Y(x',y)p(x',y))dx'.
    \end{equation}Since $p$ is a density on $\R$ we must have $\lim_{|x|\to \infty} p(x) = 0$ so that, in particular, $p^{-1}(x) \to \infty$ as $|x| \to \infty$. Consequently, since $c_X$ is bounded, a necessary condition for $\int_F \mathbf{u}^2(z)(c_X)^{-1}(z)p^{-1}(z)dz$ to be finite is for $\lim_{|x| \to \infty} \mathbf{u}(x,y) = 0$ for a.e.\ $y \in D$. Since the lower bound of integration for the integral defining $\mathbf{u}$ is $-\infty$, we have $\lim_{x \to -\infty} \mathbf{u}(x,y) = 0$, but the remaining condition amounts to
\[0 = \lim_{x \to \infty} \mathbf{u}(x,y) = \int_{-\infty}^\infty \mathrm{div}_y(c_Y(x',y)\ell_Y(x',y)p(x',y))dx', \quad \text{ for a.e.\ } y \in D,\]
which is precisely \eqref{eqn:compatibility_condition}.
\end{remark}
Assumption~\ref{ass:conditions}\ref{item:finite_growth} is needed to ensure finiteness of the robust growth rate $\lambda_\Pcal$. The second assumption is stated in a fairly abstract form but can be reduced to certain explicitly checkable integrability bounds. Indeed, if $d = 1$ then \eqref{eqn:div_PDE} becomes an ODE with unique (up to additive constant) solution given as in \eqref{eqn:u_d=1} with lower bound of integration given by $\inf\{x \in E\}$. For $d \geq 2$, we can define the Newtonian potential 
\[\Phi(x) = \begin{cases}
    \frac{1}{2\pi}\log|x|, & d = 2, \\
    \frac{1}{d(d-2)\alpha(d)}\frac{1}{|x|^{d-2}}, & d \geq 3
\end{cases},\]
where $\alpha(d)$ is the Lebesgue measure of a unit ball in $\R^d$, set \[v(x,y) = \int_E \Phi(x-x')\mathrm{div}_y(c_Y(x',y)\ell_Y(x',y)p(x',y))dx'\] and note that (at least formally) $\mathbf{u} = \nabla_x v$ is a weak solution to \eqref{eqn:div_PDE}. Indeed, by the theory of Poisson equations we have $\mathrm{div}_y(c_Y\ell_Yp) = \Delta_x v = \mathrm{div}_x \mathbf{u}$ in the weak sense, where we also used that $\Delta_x = \mathrm{div}_x \circ \nabla_x$ is the Laplacian. As such, irrespective of the dimension, only the integrability condition $\int_F \mathbf{u}(z)^\top (c_X)^{-1}(z)\mathbf{u}(z)p^{-1}(z)dz < \infty$ needs to be checked for the explicitly constructed $\mathbf{u}$ to ensure that Assumption~\ref{ass:conditions}\ref{item:divergence} holds.  Since the theory of divergence equations of the type \eqref{eqn:div_PDE} is rich and solutions other than the one constructed above may be desirable, we pose the assumption in the stated form. We explicitly construct a ${\bf u}$ solving \eqref{eqn:div_PDE} and the required integrability condition for our multivariate Ornstein--Uhlenbeck example of Section~\ref{sec:OU}. Assumption~\ref{ass:conditions}\ref{item:test_functions} is standard for these problems and is equivalent to the existence of a recurrent symmetric Markov process with covariance matrix $c$ and invariant density $p$ (see \cite[Theorem~1.6.3]{fukushimadirichlet994}). Analogously to \cite{kardaras2021ergodic,itkin2025ergodic} this assumption is crucial to ensure the class $\Pcal$ is nonempty.

To state our main results in the next section we first need to introduce a sub class of $\Pcal$. 
\begin{defn}[Finite growth class] \label{defn:P0}
    We define the class $\Pcal_0$ to be all measures $\P \in \Pcal$ which additionally satisfy
    \begin{enumerate}
    \setcounter{enumi}{2}
        \item  $\sup_{\theta \in \Theta}g(\theta;\P) < \infty.$ \label{item:Pcal0}
    \end{enumerate}
\end{defn}
The class $\Pcal_0$ restricts to measures under which infinite growth is impossible to achieve. By the general theory of growth-optimization (see Chapter~2 of \cite{karatzas2021portfolio} and, in particular, their Theorem~2.31), this amounts to a requirement that the finite variation part of $X$ be in the range of the quadratic variation process. Namely, any measure $\P \in \Pcal_0$ admits a drift of the form $dA^\P_{X,t} = c_X(Z_t)b^\P_{X,t}dt$ for some progressively measurable process $b^\P_X$. Moreover, it is easy to verify that the growth-optimal portfolio under $\P$ is given precisely by $ \theta^*_\P = b^\P_X$. A direct computation shows that its logarithmic wealth under $\P$ is given by
\[\log V^{\theta^*_\P}_T = \frac{1}{2}[L^\P]_T + L^\P_T,\qquad \text{where} \qquad L^\P_T = \int_0^T (b^\P_{X,t})^\top c_X^{1/2}(Z_t)dW_t\] is a local martingale. On the set $\{[L^\P]_\infty < \infty\}$ it follows from \cite[Lemma~1.3.2]{fernholz2002stochastic} that $L^\P_T/T \to 0$, $\P$-a.s.\ as $T \to \infty$. In this case $g( \theta^*_\P;\P) = 0$ so that \ref{item:Pcal0} is satisfied. Conversely, on the set $\{[L^\P]_\infty = \infty \}$, we can write
\[\frac{1}{T}\log V_T^{ \theta^*_\P} = \frac{[L^\P]_T}{T}\left(\frac{1}{2} + \frac{L^\P_T}{[L^\P]_T}\right).\] The Dambis, Dubins-Schwarz Theorem (\cite[Theorem~V.1.6]{revuz1999continuous}) together with the strong law of large numbers for Brownian motion ensures that $\lim_{T \to \infty} L_T^\P/[L^\P]_T = 0$, $\P$-a.s. Hence, the finite growth condition \ref{item:Pcal0} amounts to the requirement
\begin{equation} \label{eqn:bP_condition}


    \P\left(\liminf_{T \to \infty} \frac{1}{T}\int_0^T (b^\P_{X,t})^\top c_X(Z_t)b^\P_{X,t}dt < \infty\right) > 0,
\end{equation}

where we used the fact that $[L^\P]_T = \int_0^T (b^\P_{X,t})^\top c_X(Z_t)b^\P_{X,t}dt$.

\label{sec:main_results}


We are now ready to state our main results. The proofs are all postponed to Appendix~\ref{sec:proofs} for better readability. We start with a lemma guaranteeing the existence of, what turns out to be, the feedback form function characterizing the optimal strategy.
\begin{lem}[Characterization of the optimizer] \label{lem:variational}
Set 
    \[\Dcal = \{\phi: F \to \R: \phi \text{ is measurable and } \phi(\cdot,y) \in C^2(E) \text{ for a.e.\ } y \in D\}.\]


    Let Assumption~\ref{ass:inputs} and Assumption~\ref{ass:conditions}\ref{item:finite_growth}-\ref{item:divergence} be satisfied. Then there exists $\phi^* \in \Dcal$ satisfying
\begin{equation} \label{eqn:variational}
\phi^*  \in \arg\min_{\phi \in \Dcal} \int_F(\nabla_x \phi(z) - \xi(z))^\top c_X(z)(\nabla_x \phi(z) - \xi(z))p(z)dz,
\end{equation}
where we recall that $\xi$ is given by \eqref{eqn:xi}.
Moreover, $\phi^*$ is unique up to an additive function of $y$, $\nabla_x \phi^* \in L^q_{\mathrm{loc}}(F;\R^d)$ for every $q \in [2,\infty)$ and $\phi^*$ satisfies the Euler--Lagrange PDE 
 \begin{align}
 \label{eqn:Euler-Lagrange}
    & \mathrm{div}_x\big(c_X(\cdot,y)(\nabla_x \phi^*(\cdot,y) - \ell_X(\cdot,y)) p(\cdot,y)\big)  = \mathrm{div}_y(c_Y(\cdot,y)\ell_Y(\cdot,y)p(\cdot,y))
\end{align}
in $E$ for a.e.\ $y \in D$.

\end{lem}

We now state the main result of this paper.
\begin{thm}[Main result] \label{thm:main}  The robust asymptotic growth rate satisfies
\begin{equation} \label{eqn:lambda_P_thm}
    \lambda_\Pcal  = \frac{1}{2}\int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz, 
\end{equation}
where $\phi^*$ is as in Lemma~\ref{lem:variational}. 
Moreover, the strategy $\theta^*_t = \nabla_x \phi^*(Z_t)$ is robust growth-optimal in the sense that $\lambda_{\Pcal} = g(\theta^*;\P)$ for every $\P \in \Pcal_0$.    
\end{thm}



An important part of the proof, as well as a key component of our numerical examples in Section~\ref{sec:examples}, involves establishing and characterizing the worst-case measure.
\begin{prop}[Worst-case measure] \label{prop:worst_case} Let $z \in F$ be arbitrary.
    The SDE 

        \begin{equation} \label{eqn:worst_case_SDE} 
        dZ_t = \begin{pmatrix}
        c_X(Z_t)\nabla_x\phi^*(Z_t) \\ c_Y(Z_t)b_Y(Z_t)               
        \end{pmatrix}dt + c^{1/2}(Z_t)dW_t, \quad Z_0 = z,
        \end{equation}
where $\phi^*$ is given by Lemma~\ref{lem:variational}, admits a weak solution $\P^*_z \in \Pcal_0$. 
\end{prop}

The measure $\P^*_z$ is called a worst-case measure because $\theta^*$ is growth-optimal under $\P^*_z$ so that the maximal achievable asymptotic growth rate under $\P^*_z$ is the robust growth rate $\lambda_\Pcal$. 
In the sequel, the initial condition $z \in F$ will not play an impactful role and, as such, we will frequently omit it from the notation, referring by $\P^*$ to the law of the process $Z$ with dynamics \eqref{eqn:worst_case_SDE} for any arbitrary initial value $z \in F$.

\label{sec:recap_other}
To facilitate the financial discussion we briefly summarize the key findings of \cite{itkin2025ergodic} and, in the process, establish notation necessary for the subsequent sections. We focus here on the key results and main conclusions obtained from \cite[Section~5.2]{itkin2025ergodic} and refer the reader to the full article for details regarding the precise technical conditions under which the results there were proven.

The setup in \cite[Section~5.2]{itkin2025ergodic} took only the pair $(c,p)$, encompassing covariation matrix and invariant density functions respectively, as inputs and did therefore not restrict the drift of $Y$. As such, the focus there is on the class of probability measures $\Pi$ on $(\Omega,\F)$ consisting of all measures $\P$ under which\footnote{A third requirement that the laws of $(Z_t)_{t \geq 0}$ are tight under $\P$ was also required in \cite{itkin2025ergodic}, but can be removed by restricting the class of measures to have finite asymptotic growth as in the definition of $\Pcal_0$ (see also the proof of Theorem~\ref{thm:main} in Appendix~\ref{sec:proof_main}).}
\begin{enumerate}[noitemsep]
    \item \label{item:QV} $Z$ is a continuous semimartingale with quadratic variation process $ 
    [Z]_T  = \int_0^Tc(Z_t)dt$ and
    \item $Z$ satisfies the ergodic property \eqref{eqn:ergodic}. 

\end{enumerate}
The class of measures which additionally prohibits infinite asymptotic growth, as in item \ref{item:Pcal0} of Definition~\ref{defn:P0}, will be denoted by $\Pi_0$. 
The corresponding problem is then to characterize
\begin{equation}
    \lambda_{\Pi} = \sup_{\theta \in \Theta}\inf_{\P \in \Pi} g(\theta;\P)
\end{equation}
and to find the robust growth-optimal strategy $\widehat \theta$ (the growth rate $g_{\mathrm{prob}}(\cdot,\cdot)$ of \eqref{eqn:growth_rate_prob} was used in \cite{itkin2025ergodic}, but the results can be extended to the growth rate $g(\cdot,\cdot)$ of \eqref{eqn:growth_rate} as discussed in Remark~\ref{rem:growth_rate}). The key conclusion of \cite{itkin2025ergodic} was that the growth-optimal strategy $\widehat \theta$ is functionally generated by a function of $x$ only and, consequently, does not depend on the stochastic factor $Y$. Indeed, $\widehat \theta_t = \nabla \widehat \phi(X_t)$, where $\widehat \phi \in C^2(E)$ is the unique (up to additive constant) solution to the Euler--Lagrange equation
\begin{equation} \label{eqn:Euler_Lagrange_x}
\mathrm{div}\Big(a(x)\nabla \widehat \phi(x) - \frac{1}{2}\mathrm{div}\big(a(x)\big)\Big) = 0,
\end{equation}
where
\begin{equation} \label{eqn:a} 
a_{ij}(x) = \int_D (c_X)_{ij}(x,y)p(x,y)dy, \qquad i,j=1,\dots,d, \quad x \in E
\end{equation}
is the marginal volatility matrix of $X$ obtained by integrating out the variable $y$ with respect to the ergodic density $p$.
The corresponding robust growth rate is then given by
\begin{equation} \label{eqn:lambda_Pi}
\lambda_{\Pi} = \frac{1}{2}\int_{D\times E} \nabla\widehat \phi(x)^\top c_X(x,y)\nabla \widehat \phi(x)p(x,y)dydx = \frac{1}{2}\int_E \nabla \widehat \phi(x)^\top a(x) \nabla \widehat \phi(x)dx
\end{equation}
and $\widehat \theta$ is robust growth-optimal in the sense that $g(\widehat \theta;\P) = \lambda_{\Pi}$ for all $\P \in \Pi_0$. 

The corresponding worst-case measure $\widehat \P$, under which $\widehat \theta$ is growth-optimal, has to satisfy $b^{\widehat \P}_{X,t} = c_X(Z_t)\nabla \widehat \phi(X_t)$, but, unlike the setup of this paper, this does not yet specify the dynamics of $Z$. Indeed, the drift of $Y$, which is not constrained in \cite{itkin2025ergodic}, must be carefully chosen so as to yield an admissible worst-case measure. The difficulty is to find a drift process $b^{\widehat \P}_Y$ under which the process $Z$ is nonexplosive (i.e.\ stays in the domain $F$) and has $p$ as its long-term invariant density. In \cite{itkin2025ergodic} it was shown that setting $b^{\widehat \P}_{Y,t} = \nabla_y \widehat v(Z_t)$, where $\widehat v$ satisfies $\int_F \nabla_y \widehat v(z)^\top c_Y(z)\nabla_y \widehat v(z)p(z)dz < \infty$ and the PDE \cite[Equation (5.20)]{itkin2025ergodic} ensures that $\widehat \P \in \Pcal_0$. The PDE for $\widehat v$, in the notation of this paper, is given by
\begin{equation} \label{eqn:v_PDE}
    \mathrm{div}_y(c_Y(z)(\ell_Y^0(z)-\nabla_y \widehat v(z))p(z)) = -\mathrm{div}_x (c_X(z)(\ell_X(z)-\nabla \widehat \phi(x))p(z)), \qquad z \in F 
\end{equation}
where 
\begin{align}
    \ell_Y^0(z) 
     = \frac{1}{2}\Big((c^{-1}\mathrm{div} \, c)_Y(z) + \nabla_y \log p(z) + (c_Y)^{-1}(z)c_{YX}(z)\big((c^{-1}\mathrm{div} \, c)_X(z) + \nabla_x \log p(z)\big)\Big) \label{eqn:ly0}
\end{align}
is the part of $\ell_Y$ that is not affected by the input $b_Y$. As such, the dynamics of $Z$ under the worst-case measure $\widehat \P$ are given by
\begin{equation} \label{eqn:hatP_dynamics}
d\begin{pmatrix}
    X_t \\ Y_t
\end{pmatrix} = \begin{pmatrix}
    c_X(Z_t)\nabla \widehat \phi(X_t) \\
    c_Y(Z_t)\nabla_y \widehat v(Z_t)
\end{pmatrix}dt + c^{1/2}(Z_t)dW_t.    
\end{equation}
The PDE \eqref{eqn:v_PDE} formally corresponds to the stationary Fokker--Planck equation associated with \eqref{eqn:hatP_dynamics} and in \cite[Lemma~5.11]{itkin2025ergodic} it was shown, under appropriate technical assumptions, that a solution $\widehat v$ to \eqref{eqn:hatP_dynamics} exists and satisfies the required integrability bounds. In Section~\ref{sec:OU} below we will explicitly compute the worst-case measure $\widehat \P$ by solving the PDE \eqref{eqn:v_PDE} in the case where the diffusion matrix $c$ is constant and $p$ is a Gaussian density.

\label{sec:discussion}
Clearly $\Pcal \subset \Pi$ from which it immediately follows that $\lambda_\Pcal \geq \lambda_\Pi$. In fact, there is typically a strict inequality and the gap in robust growth between the setups can be quantified. Since $\widehat \theta$ achieves the same growth rate for every measure in $\Pi_0$ and $\P^* \in \Pcal_0 \subset \Pi_0$ we can deduce that
\begin{align}
    \lambda_\Pi & = g(\widehat \theta;\P^*) = \lim_{T \to \infty} \frac{1}{T}\log V^{\widehat \theta}_T \\
    & = \lim_{T \to \infty}\frac{1}{T}\int_0^T (\nabla \widehat \phi(X_t)c_X(Z_t)\nabla_x\phi^*(Z_t) - \frac{1}{2}\nabla \widehat \phi(X_t)^\top c_X(Z_t)\nabla \widehat \phi(X_t))dt  + \lim_{T \to \infty}\frac{M_T}{T} \\
    & = \int_F \nabla \widehat \phi(x)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz - \frac{1}{2}\int_F \nabla \widehat \phi(x)^\top c_X(z)\nabla \widehat \phi(x)p(z)dz,
\end{align}
where $dM_t = \sum_{i=1}^d\sum_{j=1}^{d+m}\partial_i \widehat \phi(X_t)(c_X)_{ij}(Z_t)dW_{j,t}$, the limits are understood $\P^*$-a.s.\ and the final equality followed by the ergodic property \eqref{eqn:ergodic} and  the fact that $M_T/T \to 0$ as $T \to \infty$ by \cite[Lemma~1.3.2]{fernholz2002stochastic}. 
As such, from \eqref{eqn:lambda_P_thm} we obtain
\begin{equation} \label{eqn:growth_gap}
    \lambda_{\Pcal} - \lambda_{\Pi} = \frac{1}{2}\int_F (\nabla_x \phi^*(z) - \nabla \widehat \phi(x))^\top c_X(z)(\nabla_x \phi^*(z) - \nabla \widehat \phi(x))p(z)dz.
\end{equation}
From this expression we see that assuming the drift of $Y$ is known leads to an improvement in robust growth rate in comparison to the setup that additionally robustifies over the drift of $Y$. The only exception is when $\nabla_x \phi^* = \nabla \widehat \phi$, in which case $\theta^* = \widehat \theta$ and the conditional law of $X$ given $Y$ coincides under both worst-case measures $\P^*$ and $\widehat \P$.

In Section~\ref{sec:OU}, where we study a tractable high-dimensional example, we show that this edge case can happen, but is atypical and corresponds to a very specific adversarial choice for the input $b_Y$. In the remainder of this section we assume that $\theta^* \ne \widehat \theta$.

From \eqref{eqn:growth_gap} we deduce that the investor can strictly improve their robust growth rate if they know the dynamics of the factor process $Y$. A natural question is the following: what happens to the investor's growth rate if they believe to know the correct dynamics of $Y$, but are mistaken. In this case they would use the strategy $\theta^*$, but the true measure $\P$ driving the dynamics of $Z$ is a member of $\Pi\setminus \Pcal$. As $\P$ is unknown, a natural quantity to consider is the maximum potential loss in growth from using $\theta^*$ compared to the $\Pi$-growth-optimal strategy $\widehat \theta$. Although we are unable to compute this quantity exactly we are able to get a lower bound on it since $\widehat \P \in \Pi \setminus \Pcal$. From this observation we obtain
\begin{align} 
\lambda_{\Pi} - \inf_{\P \in \Pi}g(\theta^*;\P)  \geq \lambda_{\Pi} - g(\theta^*;\widehat \P) & = \frac{1}{2}\int_F (\nabla \widehat \phi(x)-\nabla_x \phi^*(z))^\top c_X(z)(\nabla \widehat \phi(x)-\nabla_x \phi^*(z))p(z)dz \\
& = \lambda_{\Pcal} - \lambda_{\Pi} \label{eqn:growth_rate_differential},
\end{align}
where in the penultimate equality we used \eqref{eqn:lambda_Pi} in place of $\lambda_\Pi$, directly computed $g(\theta^*;\widehat \P)$, akin to how we computed $g(\widehat \theta;\P^*)$ above, and collected like terms. The final equality follows from \eqref{eqn:growth_gap}. This computation shows that the loss in growth the investor can suffer, relative to the benchmark $Y$-independent strategy $\widehat \theta$, if they infer the incorrect dynamics of $Y$ can be \emph{at least} as large as their gains from utilizing the stochastic factor (when they correctly posit the dynamics of $Y$). The upshot is that incorporating the stochastic factor in one's trading strategy can lead to an improvement in robust growth rate but, if the dynamics of the factor are incorrectly specified, can also lead to underperformance that is at least as large. As such, whether the investor should utilize the strategy $\theta^*$ or $\widehat \theta$ depends strongly on their confidence in the dynamics of the stochastic factor process they are estimating. This relationship is borne out in Figure~\ref{fig:OU_boxplot} of Section~\ref{sec:pairs_CTOU}, where we study an application to pairs trading.

We conclude this section with a discussion of how the stochastic factor process $Y$ affects the strategy $\theta^*$. Somewhat surprisingly, the feedback form function $\phi^*$ specifying $\theta^*$ is obtained by solving a collection of PDEs \eqref{eqn:Euler-Lagrange} indexed by the variable $y$. In other words, each state $y \in D$ has its own autonomous PDE that should be solved to determine the investor's optimal holdings when the process $Y$ takes the value $y$. Whence, although the optimal strategy depends on the high-dimensional $(d+m)$-dimensional process $(X,Y)$, the dimension of equation \eqref{eqn:Euler-Lagrange} that needs to be solved is only $d$-dimensional. In the context of modern machine learning applications involving high-dimensional features, one may expect $m \gg d$ in many applications making this dimension reduction significant. 

Moreover, the dissection of the PDE \eqref{eqn:Euler-Lagrange} into $y$-slices has additional benefits, from a computational point of view, as the optimal strategy $\nabla_x \phi^*(\cdot,y)$ can be solved in an online manner the first time that the factor process $Y$ takes the value $y$.\footnote{Perhaps after discretizing and binning the $y$-states.} In particular, one does not need to compute the strategy at values of the large dimensional state space $D$ which are never observed in practice. Additionally, the right hand side of \eqref{eqn:Euler-Lagrange} can be computed offline and, as such, does not increase the online run time to solve the PDE \eqref{eqn:Euler-Lagrange} and obtain the investor's robust growth-optimal holdings.

\label{sec:gradient}
If there exists a function $h: F \to \R$ such that $\xi =\nabla_x h$, then we directly see from \eqref{eqn:Euler-Lagrange_xi} that $\phi^* = h$ solves the Euler--Lagrange equation. In this case the optimal strategy is given by
\begin{equation} \label{eqn:gradient_case}
    \theta^*_t = \nabla_x h(Z_t) =\xi(Z_t) = \ell_X(Z_t) + (c_X)^{-1}(Z_t)\mathbf{u}(Z_t)p^{-1}(Z_t)
\end{equation}
When $d=1$, the gradient condition always holds regardless of the dimension of $D$ since any integrable univariate function is the derivative of its integral.

\label{sec:OU}



Here we set $E = \R^d$, $D = \R^m$ and we assume that the volatility matrix is constant, the invariant density is a centered Gaussian density and the drift of $y$ is affine. That is we take
\begin{equation} \label{eqn:Gaussian_inputs}
c(z) = c, \qquad p(z) = (2\pi)^{-\frac{d+m}{2}} (\det \Sigma)^{-1/2}\exp(-\frac{1}{2}z^\top \Sigma^{-1}z), \qquad b_Y(z) = \frac{1}{2}(\alpha + \beta z),
\end{equation}
where $c, \Sigma \in \mathbb{S}^{d+m}_{++}$ are the instantaneous and stationary covariance matrices respectively,

and $\alpha \in \R^m$, $\beta \in \R^{m\times (d+m)}$ are arbitrary at the moment, but will be chosen to ensure that the compatibility condition \eqref{eqn:compatibility_condition} is satisfied. In this section, given an invertible matrix $M$ we write $M^{-1}_X$ for $(M^{-1})_X$, and similarly for $M^{-1}_{XY},M^{-1}_{YX},M^{-1}_Y$, as these quantities appear frequently in the ensuing calculations and this convention improves the aesthetics of the lengthy formulas. We continue to write $(M_X)^{-1}$ and $(M_Y)^{-1}$ for the inverse of a particular block. 

Next we compute that
\[\ell_X(x,y) = -\frac{1}{2}(Ax + By), \qquad \ell_Y(x,y) = -\frac{1}{2}(Cx + Dy - \alpha),\]
where
\begin{align}
    A & = \Sigma^{-1}_X + (c_X)^{-1}c_{XY}\Sigma^{-1}_{YX}, \qquad & B  = \Sigma^{-1}_{XY} + (c_X)^{-1}c_{XY}\Sigma^{-1}_Y, \\
    C & = \Sigma^{-1}_{YX}+(c_Y)^{-1}c_{YX}\Sigma^{-1}_X+\beta_X, \qquad & D = \Sigma^{-1}_Y + (c_Y)^{-1}c_{YX}\Sigma^{-1}_{XY} + \beta_Y, 
\end{align}

and we split up $\beta = \begin{bmatrix} \beta_X & \beta_Y \end{bmatrix}$ so that $\beta_X \in \R^{m\times d}$ and $\beta_Y \in \R^{m \times m}$. By interchanging derivative and integral we see that the compatibility condition \eqref{eqn:compatibility_condition} here becomes 
\begin{align}
    0 = \int_{\R^d}\mathrm{div}_y(c_Y\ell_Y(x,y)p(x,y))dx & = -\frac{1}{2} \mathrm{div}_y\left(c_Y\int_{\R^d}(Cx + Dy -\alpha)p(x,y)dx\right) \\
    & = -\frac{1}{2}\mathrm{div}_y\Big(c_Y\big((C\Sigma_{XY}(\Sigma_Y)^{-1}+D)y - \alpha\big)p_Y(y)\Big),
\end{align}
where in the final equality we computed the conditional expectation of $CX|Y$ for $(X,Y) \sim N(0,\Sigma)$ and denoted by $p_Y$ the marginal density of $Y$.
It's clear that this condition holds for every $y \in \R^m$ if and only if $\alpha = 0$ and $C\Sigma_{XY}(\Sigma_Y)^{-1} +D = 0$. The latter condition amounts to requiring
\begin{equation} \label{eqn:beta_Y}
\beta_Y = -(\Sigma^{-1}_Y + (c_Y)^{-1}c_{YX}\Sigma^{-1}_{XY} + C\Sigma_{XY}(\Sigma_Y)^{-1}), 
\end{equation}
while the input $\beta_X$ remains free.

With the inputs now fixed we check Assumption~\ref{ass:conditions}. Item \ref{item:finite_growth} clearly holds as $\ell_X$ and $\ell_Y$ are both linear and item \ref{item:test_functions} is easily seen to hold due to the Gaussian tails of $p$ by choosing, for example, $\chi_n = 1*\eta_{1/n}$ for a standard mollifier $(\eta_\epsilon)_{\epsilon > 0}$. It remains to establish Assumption~\ref{ass:conditions}\ref{item:divergence}. Here, the PDE \eqref{eqn:div_PDE} for ${\bf u}$ is 
 \begin{equation} \label{eqn:u_Gaussian}
 \mathrm{div}_x {\bf u}(x,y) = -\frac{1}{2}\mathrm{div}_y\big(c_YC(x-\Sigma_{XY}(\Sigma_Y)^{-1}y)p(x,y)\big).
 \end{equation}
An explicit solution is given by
\[ {\bf u}(x,y) = - \frac{1}{2}(\Sigma_X^{-1})^{-1}C^\top c_Y(\Sigma_{YX}^{-1}x + \Sigma_Y^{-1}y)p(x,y).\]
Indeed, writing $M = (\Sigma_X^{-1})^{-1}C^\top c_Y$ we have that
\begin{align}
\mathrm{div}_x {\bf u}(x,y) & = \frac{1}{2}\mathrm{div}_x(M\nabla_y p(x,y)) = \frac{1}{2} \sum_{i=1}^d\sum_{j=1}^m M_{ij}\partial_{x_i}\partial_{y_j}p(x,y)=  \frac{1}{2} \sum_{j=1}^m\sum_{i=1}^d M^\top_{ji}\partial_{y_i}\partial_{x_i}p(x,y) \\
& = \frac{1}{2}\mathrm{div}_y(M^\top \nabla_x p(x,y)) = -\frac{1}{2}\mathrm{div}_y(c_YC(\Sigma_X^{-1})^{-1}(\Sigma^{-1}_X x + \Sigma^{-1}_{XY}y)p(x,y)) \label{eqn:u_verification_Gaussian} \\
& = -\frac{1}{2}\mathrm{div}_y\big(c_YC(x-\Sigma_{XY}(\Sigma_Y)^{-1}y)p(x,y)\big).
\end{align}




In the last step we used that $(\Sigma_X^{-1})^{-1}\Sigma^{-1}_{XY} = -\Sigma_{XY}(\Sigma_Y)^{-1}$, which follows from the fact that $\Sigma^{-1}$ is the inverse of $\Sigma$. Indeed, from this inverse relationship we have that $\Sigma^{-1}_X\Sigma_{XY} + \Sigma^{-1}_{XY}\Sigma_Y = 0$, so bringing the first term to the other side of the equality and multiplying both sides on the left by $(\Sigma_X^{-1})^{-1}$ and on the right by $(\Sigma_Y)^{-1}$ establishes the identity. Moreover, we have
\begin{align}
    \int_{\R^{d+m}} {\bf u}^\top(z) & (c_X)^{-1}(z)  {\bf u}(z) p^{-1}(z)dz \\
    & = \frac{1}{4}\int_{\R^{d+m}} (x-\Sigma_{XY}\Sigma_Y^{-1}y)^\top M^\top (c_X)^{-1}M(x-\Sigma_{XY}\Sigma_Y^{-1}y)p(x,y)dxdy < \infty,
\end{align}
so that Assumption~\ref{ass:conditions}\ref{item:divergence} holds. 

With the assumptions verified, Theorem~\ref{thm:main} yields a robust optimal strategy characterized by the solution of the PDE \eqref{eqn:Euler-Lagrange}. Here we observe that both $\ell_X$ and $(c_X)^{-1} {\bf u} p^{-1}$ are linear in $x$, so that $\xi(x,y) = \nabla_x Q(x,y)$ for some quadratic function $Q$. It follows from the discussion in Section~\ref{sec:gradient} that the optimal strategy is given by
\[\theta^*_t = \nabla_x \phi^*(Z_t) =  -\frac{1}{2}\underbrace{(A+(c_X)^{-1}(\Sigma_X^{-1})^{-1}C^\top c_Y\Sigma^{-1}_{YX})}_{M_X}X_t -\frac{1}{2} \underbrace{(B + (c_X)^{-1}(\Sigma_X^{-1})^{-1}C^\top c_Y\Sigma_Y^{-1})}_{M_Y}Y_t\] 








and the robust-optimal growth rate is given by
\begin{align}
    \lambda_{\Pcal} & = \frac{1}{2}\int_{\R^{d+m}}\nabla_x \phi^*(z)^\top c_X\nabla_x \phi^*(z)p(z)dz \\
    & = \frac{1}{8}\mathrm{Tr}(M_X^\top c_X M_X\Sigma_X)+ \frac{1}{4}\mathrm{Tr}(M_X^\top c_XM_Y\Sigma_{YX}) + \frac{1}{8}\mathrm{Tr}(M_Y^\top c_XM_Y\Sigma_Y). \label{eqn:lambda_P_Gaussian}
\end{align} 
Additionally, from Proposition~\ref{prop:worst_case} we see that the $Z = (X,Y)$ is an OU process under the worst-case measure $\P^*$,
\[d\begin{pmatrix}
    X_t \\ Y_t 
\end{pmatrix} = \begin{pmatrix}
    -\frac{1}{2}c_XM_XX_t  -\frac{1}{2}c_XM_YY_t \\
    \frac{1}{2}c_Y\beta_X X_t - \frac{1}{2}c_Y(\Sigma^{-1}_Y + (c_Y)^{-1}c_{YX}\Sigma^{-1}_{XY} + C\Sigma_{XY}(\Sigma_Y)^{-1})Y_t
\end{pmatrix}dt + c^{1/2}dW_t,\]
where we recalled the compatibility condition \eqref{eqn:beta_Y} for $\beta_Y$.

We now compare this setting and optimal strategy to the setup in \cite{itkin2025ergodic}.  The matrix $a(x)$ of \eqref{eqn:a} here is given by $c_Xp_X(x)$, where $p_X$ is the marginal density of $X$, so it is easy to see by inspection that $\widehat \phi(x) = \frac{1}{2}\log p_X(x)$ solves \eqref{eqn:Euler_Lagrange_x}. As such, the  robust growth-optimal strategy for the class $\Pi$ is given by 
\[\widehat \theta_t = \nabla \widehat \phi(X_t) = \frac{1}{2}\nabla \log p_X(X_t) =-\frac{1}{2}(\Sigma_X)^{-1}X_t.\]
To find the dynamics of the worst-case measure $\widehat \P$ we solve the PDE \eqref{eqn:v_PDE} for $\nabla_y \widehat v$, which has explicit solution given by
\begin{align} 
    \nabla_y \widehat v(x,y) & = \ell_Y^0(x,y) -  \frac{1}{2}(c_Y)^{-1}(\Sigma^{-1}_Y)^{-1}B^\top c_X(\Sigma^{-1}_X x +\Sigma^{-1}_{XY}y) \\
    & = - \frac{1}{2}(C^0x+D^0y) -  \frac{1}{2}(c_Y)^{-1}(\Sigma^{-1}_Y)^{-1}B^\top c_X(\Sigma^{-1}_X x +\Sigma^{-1}_{XY}y), \label{eqn:hatv_Gaussian}
\end{align}
where $C^0 = C-\beta_X$ and $D^0 = D-\beta_Y$ are the parts of $C$ and $D$ which are not affected by $\beta$.
We note that the right hand side for $\nabla_y \widehat v$ above is linear in $y$ and, as such, is indeed the gradient of some quadratic function $\widehat v$, which we do not write out explicitly. One can easily verify that \eqref{eqn:hatv_Gaussian} satisfies \eqref{eqn:v_PDE} and the verification follows in a very similar fashion to the computations in \eqref{eqn:u_verification_Gaussian}, where we verified that the explicit solution for ${\bf u}$ solves \eqref{eqn:u_Gaussian}, so we omit the verification here. 













It now follows from \eqref{eqn:hatP_dynamics} that under the worst-case measure $\widehat \P$, $Z$ follows a different OU process characterized by the dynamics
\[d\begin{pmatrix}
    X_t \\ Y_t
\end{pmatrix} = \begin{pmatrix}
    -\frac{1}{2}c_X(\Sigma_X)^{-1}X_t \\
    -\frac{1}{2}c_Y(C^0X_t +D^0Y_t) -\frac{1}{2}(\Sigma^{-1}_Y)^{-1}B^\top c_X(\Sigma^{-1}_X X_t +\Sigma^{-1}_{XY}Y_t)
\end{pmatrix}dt + c^{1/2}dW_t. \]

The growth rate of the robust-optimal strategy $\widehat \theta$ is the same under both $\P^*$ and $\widehat \P$, as both measures belong to $\Pi_0$. This growth rate is given by
\[\lambda_{\Pi} = g(\widehat \theta;\P^*) = g(\widehat \theta;\widehat \P) = \frac{1}{2}\int_{\R^d}\nabla \widehat \phi(x)^\top c_X \nabla \widehat \phi(x)p_X(x)dx = \frac{1}{8}\mathrm{Tr}((\Sigma_X)^{-1}c_X).\]
Conversely, despite $\theta^*$ having the growth-rate invariance property over the class $\Pcal$, this property does not extend to the larger class $\Pi$  as discussed in Section~\ref{sec:discussion}.  We are able to obtain by direct calculation that
\begin{align}
    g(\theta^*,\widehat \P) & = \int_{\R^{d+m}}\nabla_x\phi^*(z)^\top c_X\nabla\widehat \phi(x)p(z)dz - \frac{1}{2}\int_{\R^{d+m}}\nabla_x \phi^*(z)^\top c_X\nabla_x\phi^*(z)p(z)dz \\
    & = \frac{1}{4}\mathrm{Tr}(M_X^\top c_X) + \frac{1}{4}\mathrm{Tr}(M_Y^\top c_X(\Sigma_X)^{-1}\Sigma_{XY}) -  \lambda_{\Pcal},
\end{align}
where $\lambda_{\Pcal}$ was computed in \eqref{eqn:lambda_P_Gaussian}. We conclude this section by noting that $M_Y = 0$ if and only if 
\[\beta_X = -\Sigma^{-1}_{YX}- (c_Y)^{-1}c_{YX}\Sigma^{-1}_X - (c_Y)^{-1}(\Sigma^{-1}_Y)^{-1}B^\top c_X\Sigma^{-1}_X.\]
In this case it can be directly checked that $\theta^* = \widehat \theta$ and $\P^* = \widehat \P$ corresponding to the special
edge case mentioned in Section~\ref{sec:discussion} where knowledge of the stochastic factor does not increase the investor's robust growth rate. For all other choices of $\beta_X \in \R^{m \times d}$ the strategies $\theta^*$ and $\widehat \theta$ differ and the strict inequality $\lambda_\Pcal > \lambda_\Pi$ holds. 
\begin{remark}
Notice -- as a side result -- that our robust optimal growth rate problems under ergodicity maintain a linear (quadratic) character for drifts and strategies with respect to $\mathcal{P}$ and $\Pi$, respectively: their solutions equal the solutions of the corresponding linear quadratic problems formulated in a purely Gaussian universe.
\end{remark}

\label{sec:pairs_CTOU}
In the pairs trading literature, models have been proposed to capture mean reversion properties of the spread process.\footnote{Some authors model the spread measured in logarithmic terms $a\log S^1_t - b\log S^2_t$, but since we wish to directly relate the spread to a tradeable security we work with the asset spread process \eqref{eqn:spread} instead.} A popular choice (see \cite{liu2017intraday,leung2018optimal}) is the so-called \emph{Central Tendency Ornstein--Uhlenbeck} (CTOU) model,
\begin{equation} \label{eqn:CTOU}
\begin{aligned}
    dX_t & = - \kappa_X(X_t-Y_t)dt&  + \sqrt{c_X} dW^X_t, \\
    dY_t & = -\kappa_YY_tdt&  + \sqrt{c_Y}dW^Y_t.
\end{aligned}
\end{equation}
Here $X$ mean reverts to the stochastic level $Y$ with mean reversion speed $\kappa_X > 0$ and $Y$ follows autonomous OU dynamics with mean reversion speed $\kappa_Y>0$. The volatility levels $\sqrt{c_X}$ an $\sqrt{c_Y}$ are assumed to be constant and the Brownian motions $W^X$ and $W^Y$ are uncorrelated. The bivariate process $Z = (X,Y)$ has $\Ncal(0,\Sigma)$ as its unique stationary measure, where
\begin{equation} \label{eqn:Sigma_pairs}
\Sigma = \begin{bmatrix} \frac{c_X}{2\kappa_X} + \frac{c_Y\kappa_X}{2\kappa_Y(\kappa_X+\kappa_Y)}& \frac{c_Y\kappa_X}{2\kappa_Y(\kappa_X+\kappa_Y)} \\ \frac{c_Y\kappa_X}{2\kappa_Y(\kappa_X+\kappa_Y)}
& \frac{c_Y}{2\kappa_Y}
\end{bmatrix}.
\end{equation}



Although a very useful model to inform portfolio selection, the CTOU model imposes strong modelling assumptions. In particular, the linear drift dynamics for $X$ directly imply that the growth-optimal portfolio is a linear feedback form function,
\[\theta^{\mathrm{CTOU}}_t = -\frac{\kappa_X}{c_X}(X_t-Y_t).\]

  We will apply the robust growth-optimal framework developed in this paper and in \cite{itkin2025ergodic} to study how robust the conclusions of the CTOU model are and what effects different assumptions about model uncertainty have on the strategy and the associated growth rate. To this end, we take a constant diagonal volatility matrix $c$ and a centered bivariate Gaussian invariant density $p$ with stationary covariance matrix $\Sigma$ given by \eqref{eqn:Sigma_pairs} as inputs, which puts us in the setting of Section~\ref{sec:OU} with $m=d=1$. These choices pin down the class of measures $\Pi$. To specify $\Pcal$ we additionally take $b_Y(y) = - \frac{\kappa_Y}{c_Y}y$ consistent with the CTOU model, which corresponds to $\beta_X = 0$ in the notation of Section~\ref{sec:OU}. 

  Since $Y$ is an autonomous one-dimensional process its  linear drift specification may be easier to statistically justify from data than the corresponding one for $X$. Moreover, if the investor uses exponentially weighted updates to their forecast $Y$, then the investor is effectively guaranteeing  (in the continuous-time limit) that the drift dynamics of $Y$ are as assumed. In this context, the class $\Pcal$ can be viewed as the mathematical idealization of expressing the investor's high confidence in the evolution of the autonomous process $Y$ relative to her lower confidence estimating the drift of the coupled process $X$. The class $\Pi$, in contrast, expresses equal uncertainty in the drift specifications of both $X$ and $Y$ and seeks to robustify over both those inputs.

Remarkably, the formulas of Example~\ref{sec:OU} show that $\theta^* = \theta^{\mathrm{CTOU}}$ and that the worst-case measure $\P^*$, for the class $\Pcal$, is a CTOU process. As such, the CTOU model can be viewed as a conservative modelling choice when considering measures that are consistent with a constant volatility matrix, centered Gaussian invariant density with covariance matrix $\Sigma$ of \eqref{eqn:Sigma_pairs} and autonomous OU dynamics for $Y$. In contrast, the strategy $\widehat \theta$ in this case is given by
\[\widehat \theta_t = - \frac{\kappa_X(\kappa_X +\kappa_Y)}{c_X(\kappa_X+\kappa_Y) + c_Y\kappa_Y}X_t\]
and the dynamics of $(X,Y)$ under $\widehat \P$, which is the worst-case measure for $\Pi$, are given by
\begin{align}
dX_t & = - \frac{c_X\kappa_X(\kappa_X +\kappa_Y)}{c_X(\kappa_X+\kappa_Y) + c_Y\kappa_Y}X_tdt & + \sqrt{c_X}dW^X_t, \\
dY_t & = \left(\frac{c_Y\kappa_X^2(\kappa_X+\kappa_Y)}{c_Y\kappa_X^2 + c_X\kappa_Y(\kappa_X+\kappa_Y)}X_t - \frac{(\kappa_X+\kappa_Y)(c_Y\kappa_X^2 + c_X\kappa_Y^2)}{c_Y\kappa_X^2 + c_X\kappa_Y(\kappa_X + \kappa_Y)}Y_t\right)dt & + \sqrt{c_Y}dW^Y_t.
\end{align}
The dynamics under $\widehat \P$ are consistent with the volatility matrix $c$ and invariant density $p$, but admits a different drift for $Y$ than the CTOU process does. The main feature of $\widehat \P$ is that it prescribes adversarial dynamics for $X$, making $X$ an autonomous diffusion. This is in stark contrast to the CTOU model \eqref{eqn:CTOU} where $Y$ was an autonomous diffusion and $X$ mean reverted to the stochastic target $Y$. It is evident that the strategy $\theta^*$ is suboptimal under $\widehat \P$ as it uses the superfluous factor $Y$, which does not appear in the dynamics of $X$, to make investment decisions. 



We now numerically illustrate the performance of the strategies. Our experiments use the following model parameters, in annual units, which are representative of a profitable pairs trading opportunity, 
\begin{equation} \label{eqn:OU_params} 
c_X = 0.04, \quad  c_Y = 0.0225, \quad \kappa_X = 1, \quad \kappa_Y = 1/2.
\end{equation}
Figure~\ref{fig:OU_boxplot} shows boxplots of the growth-rates $\frac{1}{T}\log V^\theta_T$  simulated up to the horizons $T \in \{10,20,30\}$ for $\theta \in \{\theta^*,\widehat \theta\}$ and under both worst-case measures $\P^*$ and $\widehat \P$.

As predicted by \eqref{eqn:growth_gap} and \eqref{eqn:growth_rate_differential}, the results show that the strategy $\theta^*$ outperforms $\widehat \theta$ under $\P^*$ and underperforms it under $\widehat \P$ by the same growth rate differential. The outperformance is substantial with $\lambda_{\Pcal} - \lambda_\Pi \approx 0.2$ showcasing the potential long-term benefits of utilizing the stochastic factor.  On the flip side, $g(\theta^*;\widehat \P) =-0.06$ leading not only to underperformance, but to investment losses when the underlying dynamics correspond to the worst-case measure $\widehat \P$ for the class $\Pi$. In contrast, the strategy $\widehat \theta$ is ambivalent to the underlying measure leading to a solid annual growth rate of approximately 0.14. Although not theoretically studied, the simulations also show that the growth-rate when using $\widehat \theta$ converges faster than its counterpart $\theta^*$ under both measures. 



Next, we compare the holdings prescribed by the two strategies. Figure~\ref{fig:OU_slices} plots the feedback form function $\widehat \phi'$ specifying the strategy $\widehat \theta$ together with the slices $\partial_x  \phi^*(\cdot,y)$, for certain fixed values of $y$, which specify the holdings $\theta^*$ when $Y$ takes the value y. We see that both strategies take short positions in $X$ when it is positive and long positions when it is negative, as expected for a pairs trading strategy. However, $\widehat \phi'$ is symmetric around zero, while $\partial_x\phi^*(\cdot,y)$ is symmetric around $y$ since the latter anticipates that the spread process $X$ is mean reverting to the level $y$. Additionally, although all of the slices $\partial_x \phi^*(\cdot,y)$ are parallel to each other, they are not parallel to $\widehat \phi'$. Indeed, the former has a steeper slope, which means that an investor using $\theta^*$ trades more aggressively than one using $\widehat \theta$ since an equal sized movement in $X$ leads to a larger change in the holdings $\theta^*$ than for its counterpart $\widehat \theta$. The less aggressive behaviour of $\widehat \theta$ is consistent with its role as the robust growth-optimal strategy under the larger class of measures $\Pi$.

Next we turn our attention to the construction of the worst-case measure $\P^*$. Since we only have Sobolev regularity for $(x,y) \mapsto \nabla_x \phi^*(x,y)$, rather than say joint Lipschitz continuity or differentiability in $x$ and $y$, classic SDE stability and recurrence results are not available. Instead, the proof follows in a very similar fashion to \cite[Theorem~5.5]{itkin2025ergodic} using very recent results on generalized Dirichlet forms. We refer to the text \cite{leeanalytic2022} for an accessible presentation of the generalized Dirichlet form results and for any notation and terminology below that is not explicitly defined in this paper.

To carry out this program we introduce the symmetric Dirichlet form $(\Ecal^0,D(\Ecal^0))$ as the closure on $L^2(F,\mu)$ of
\[\Ecal^0(u,v) = \int_F \nabla u(z)^\top c(z)\nabla v(z)p(z)dz; \qquad u,v \in C_c^\infty(F),\]
where $L^2(F,\mu)$ is the space of square-integrable functions with respect to the measure $d\mu(z) = p(z)dz$. The generator $(L^0,D(L^0))$ corresponding to this Dirichlet form is readily seen, via integration by parts, to satisfy
\[L^0u  = \frac{1}{2}\mathrm{Tr}(c\nabla^2u) + (\ell^0)^\top c \nabla u; \qquad u \in C_c^\infty(F),\]
where $\ell^0 = \frac{1}{2}(c)^{-1}\mathrm{div} \, c + \frac{1}{2}\nabla \log p$. Next we define the quantity
\[\beta(z) = \begin{pmatrix}c_X(z)\nabla_x \phi^*(z) \\ c_Y(z)b_Y(z) \end{pmatrix} - c(z)\ell^0(z) = \begin{pmatrix}
    c_X(z)(\nabla_x \phi^*(z) - \ell_X(z)) \\ -c_Y(z)\ell_Y(z)
\end{pmatrix},\]
where we recall $\ell_X$ and $\ell_Y$ given by \eqref{eqn:ell_X} and \eqref{eqn:ell_Y} respectively.
The vector field $\beta $ will play the role of a $\mu$-divergence free perturbation to the symmetric Dirichlet form. The construction of the measures $(\P^*_z)_{z \in F}$ crucially relies on the following technical lemma.

\begin{lem} \label{lem:L1_semigroup}
    There exists an operator $(L,D(L))$ on $L^1(F,\mu)$ such that the following hold:
    \begin{enumerate}
        \item $C_c^\infty(F) \subset D(L)$ and
        \[Lu = L^0u + \beta^\top \nabla u; \qquad u \in C_c^\infty(F),\]
    \item For every bounded $u \in D(L)$ and every compactly supported and bounded $v \in W^{1,2}(F)$ we have
    \begin{equation} \label{eqn:IBP}
        \Ecal^0(u,v) - \int_F v(z)\beta(z)^\top \nabla u(z)p(z)dz =- \int_F v(z)Lu(z)p(z)dz,
    \end{equation}
    \item $(L,D(L))$ generates a strongly continuous contraction semigroup $(T_t)_{t \geq 0}$ on $L^1(F,\mu)$. Moreover, $T_tf$ has a continuous version $P_tf$ for every $f \in \Bcal_b(F)$ and $t > 0$. \label{item:semigroup}
        \end{enumerate}
\end{lem}
\begin{proof}
    The first two items of the lemma will follow from \cite[Theorem~1.5]{stannatdirichlet1999} and the last item from \cite[Theorem~2.31]{leeanalytic2022}(which is applicable courtesy of \cite[Remark~2.40]{leeanalytic2022}) as soon as we verify that $\beta \in L^q_{\mathrm{loc}}(F;\R^{d+m})$ for some $q > d+m$ and that
    \begin{equation} \label{eqn:divergence_free} 
    \int_F (L^0u(z) + \beta(z)^\top \nabla u(z) )p(z)dz = 0; \qquad \forall u \in C_c^\infty(F).
    \end{equation} We deduce from Assumption~\ref{ass:inputs} on $c\,, p$ and $b_Y$ together with the $L^q_{\mathrm{loc}}(F;\R^d)$ result for $\nabla_x \phi^*$ guaranteed by Lemma~\ref{lem:variational} that $\beta \in L^q_{\mathrm{loc}}(F;\R^{d+m})$ for every $q \in [2,\infty)$. In particular this holds for $q > d+m$. Next a direct calculation shows that $L^0 u(z)p(z) = \mathrm{div}(c(z) \nabla u(z) p(z))$ for every $u \in C_c^\infty(F)$. The divergence theorem, in turn, yields $\int_F L^0 u(z) p(z)dz = 0$. To handle the perturbation term we similarly use the divergence theorem,
    \begin{align}
        \int_F \beta(z)^\top \nabla u(z)& p(z)dz = -\int_F \mathrm{div}(\beta(z)p(z))u(z)dz  \\ & =
        -\int_F \Big(\mathrm{div}_x\big(c_X(z)(\nabla_x\phi^*(z)-\ell_X(z))p(z)\big) - \mathrm{div}_y(c_Y(z)\ell_Y(z)p(z))\Big)u(z)dz = 0,
    \end{align}
    where in the last equality we used \eqref{eqn:Euler-Lagrange}. This establishes \eqref{eqn:divergence_free} and completes the proof.
\end{proof} 
A consequence of Lemma~\ref{lem:L1_semigroup} is the existence of a diffusion process with semigroup $(P_t)_{t > 0}$ given in Lemma~\ref{lem:L1_semigroup}\ref{item:semigroup}. Formally we augment the state space $F$ with a cemetery state $\Delta$ by letting $F_\Delta = F \cup \{\Delta\}$ be the one-point compactification of $F$. Next we introduce the measurable space $(\Omega_\Delta,\Fcal_\Delta)$ given by
\[\Omega_\Delta = \{\omega \in C([0,\infty);F_\Delta): \omega_{t+h} = \Delta \text{ if } \omega_t = \Delta \text{ for all } h,t\geq 0\}\] 
and $\Fcal_\Delta$ being the Borel $\sigma$-algebra induced by the topology of local uniform convergence. With a slight abuse of notation we denote by $Z$ the coordinate process on this space. Then we have the following existence result
\begin{lem} \label{lem:diffusion_existence}
    There exists a diffusion  
    \[\mathbb{M} = (\Omega_\Delta,\Fcal_\Delta,(\Fcal_t)_{t \geq 0},(Z_t)_{t \geq 0},(\P^*_z)_{z \in F_\Delta})\]
    with state space $F$, lifetime $\zeta := \inf\{t \geq 0:Z_t = \Delta\}$ and transition semigroup $(P_t)_{t \geq 0}$ of Lemma~\ref{lem:L1_semigroup}\ref{item:semigroup}. That is for every $t \geq 0, \, z \in F$ and $f \in \Bcal_b(F)$ it holds that $P_tf(z) =  \E^*_z[f(Z_t)]$ where $\E^*_z[\cdot]$ denotes expectation under $\P^*_z$.
\end{lem}
The proof of Lemma~\ref{lem:diffusion_existence} follows in exactly the same way as the proof of \cite[Lemma~C.3]{itkin2025ergodic}, as a consequence of Lemma~\ref{lem:L1_semigroup}, and is hence omitted. Next, we show that $\mathbb{M}$ is a global weak solution to \eqref{eqn:worst_case_SDE} and is ergodic with invariant measure $\mu$.

\begin{lem} \label{lem:diffusion_properties}
    The process $\mathbb{M}$ of Lemma~\ref{lem:diffusion_existence} is strictly irreducible, recurrent, nonexplosive and ergodic with invariant measure $\mu$. Moreover, $\mathbb{M}$ is a weak solution to $\eqref{eqn:worst_case_SDE}$ and \eqref{eqn:ergodic} holds for every locally bounded $h \in L^1(F,\mu)$.
\end{lem}
\begin{proof} The strict irreducibility claim is a consequence of \cite[Proposition~2.39]{leeanalytic2022}. Next, we will prove recurrence using the criteria developed in \cite{gim2018recurrence} together with Assumption~\ref{ass:conditions}\ref{item:test_functions}. Indeed, Assumption~\ref{ass:conditions}\ref{item:test_functions} ensures that there exist functions $\chi_n \in C_c^\infty(F)$ with $0 \leq \chi_n \leq 1$, converging pointwise to one and such that
\begin{align} 
\lim_{n \to \infty} &  \Ecal^0(\chi_n,\chi_n) = \int_F \nabla \chi_n(z)^\top c(z)\nabla \chi_n(z)p(z)dz \\
& \leq \lim_{n \to \infty}2\left(\int_F \nabla_x \chi_n(z)^\top c_X(z)\nabla_x\chi_n(z)p(z)dz + \int_F \nabla_y \chi_n(z)^\top c_Y(z)\nabla_y\chi_n(z)p(z)dz\right)  = 0,
\end{align}
where we used the inequality $v^\top c(z) v \leq 2(v_X^\top c_X(z)v_X + v_Y^\top c_Y(z)v_Y)$ for any $v \in \R^{d+m}$, which holds since $c(z)$ is positive definite.
Next, we use Cauchy--Schwarz to deduce that
\begin{align}
     & \int_F|\beta^\top \nabla \chi_n(z)|p(z)dz  = \int_F|(\nabla_x \phi^*(z) - \ell_X(z))^\top c_X(z)\nabla_x \chi_n(z) - \ell_Y(z)^\top c_Y(z) \nabla_y \chi_n(z)\big|p(z)dz \\
      \leq & \bigg(\!\int_F (\nabla_x \phi^*(z)-\ell_X(z))^\top c_X(z)(\nabla_x \phi^*(z) - \ell_X(z))p(z)dz\!\bigg)^{\!\frac{1}{2}}\!\bigg(\!\int_F \nabla_x \chi_n(z)^\top c_X(z)\nabla_x \chi_n(z)p(z)dz\!\bigg)^\frac{1}{2} \\
     & \quad + \left(\int_F \ell_Y(z)^\top c_Y(z)\ell_Y(z)p(z)dz\right)^\frac{1}{2}\left(\int_F\nabla_y \chi_n(z)^\top c_Y(z)\nabla_y \chi_n(z)p(z)dz\right)^\frac{1}{2}. \label{eqn:chi_n_bound}
\end{align}
Since $\phi^*$ is a minimizer of the variational problem \eqref{eqn:variational} we deduce from the fact that $0 \in \Dcal$, the bound $\int_F\nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz \leq \int_F \xi(z)^\top c_X(z)\xi(z)p(z)dz$. Together with the integrability bounds of Assumption~\ref{ass:conditions}\ref{item:finite_growth} and \ref{item:divergence} we obtain that the integral terms on the right hand side of \eqref{eqn:chi_n_bound} are finite. Assumption~\ref{ass:conditions}\ref{item:test_functions} then yields the convergence to zero of the terms in \eqref{eqn:chi_n_bound} as $n \to \infty$. In summary, we have shown that
\[\lim_{n \to \infty} \left(\Ecal^0(\chi_n,\chi_n) + \int_F|\beta^\top(z)\nabla \chi_n(z)|p(z)dz\right)  = 0.\]
Remark~15 and Corollary~8(b) in \cite{gim2018recurrence} now yield recurrence of the semigroup $(P_t)_{t \geq 0}$, which implies recurrence of $\mathbb{M}$ as $(P_t)_{t \geq 0}$ is its semigroup. A consequence of recurrence is nonexplosivity of $\mathbb{M}$, which in this context can be deduced from \cite[Corollary~3.23]{leeanalytic2022} together with conservativity of $(P_t)_{t \geq 0}$, which is an immediate consequence of its recurrence. That $\mu$ is an ergodic measure for $\mathcal{M}$ and the ergodic property \eqref{eqn:ergodic} holds now follows in exactly the same way as in the proof of \cite[Lemma~C.5]{itkin2025ergodic}. That $\mathbb{M}$ is a weak solution to \eqref{eqn:worst_case_SDE} follows via standard arguments connecting the process $\mathbb{M}$ to the martingale problem for the generator $L$ via \eqref{eqn:IBP} and using the well known equivalence between martingale problems and weak solutions of SDEs. This is precisely the result \cite[Theorem~3.22(i)]{leeanalytic2022}, which we obtain here by following the proof of \cite[Chapter~3]{leeanalytic2022} verbatim from Proposition~3.12 onwards, but in our setting of a general open domain $F$ rather than all of $\R^{d+m}$. This completes the proof.   \end{proof}
We are now ready to show that $\P^*_z$ is in $\Pcal_0$.
\begin{proof}[Proof of Proposition~\ref{prop:worst_case}]
The process $\mathbb{M}$ of Lemma~\ref{lem:diffusion_existence} has been shown to satisfy \eqref{eqn:opt_wealth_easy} and the ergodic property \eqref{eqn:ergodic} in Lemma~\ref{lem:diffusion_properties}. As such, by definition of $\Pcal$,  its law $\P^*_z \in \Pcal$ for every $z \in F$.

It now remains to show the existence of a growth-optimal portfolio with finite asymptotic growth rate to deduce its inclusion in $\Pcal_0$. The discussion at the beginning of Section~\ref{sec:main_results} yields that \eqref{eqn:bP_condition} must hold where we replace $\P$ with $\P^*_z$ and $b_X^\P$ with $\nabla_x \phi^*(Z)$. But using the ergodic property and that $\phi^*$ is a minimizer for the variational problem \eqref{eqn:variational} we see that 
\[\lim_{T \to \infty} \frac{1}{T}\int_0^T \nabla_x \phi^*(Z_t)^\top c_X(Z_t)\nabla_x \phi^*(Z_t)dt = \int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz < \infty; \qquad \P^*_z\text{-a.s.}\]
This shows that \eqref{eqn:bP_condition} holds and, in fact, that
\begin{equation} \label{eqn:worst_case_growth}
    \sup_{\theta \in \Theta} g(\theta;\P^*_z) = g(\theta^*;\P^*_z) = \frac{1}{2}\int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz.
\end{equation}
This establishes that $\P^*_z \in \Pcal_0$ and completes the proof.
\end{proof}

\label{sec:proof_main}
It now just remains to prove the main result Theorem~\ref{thm:main}. To accomplish this we need the following lemma.
\begin{lem}  \label{lem:approx}









    There exist functions $ \phi_n \in C_c^\infty(F)$ such that 
    \[\lim_{n \to \infty} \int_F (\nabla_x \phi_n(z)-\nabla_x \phi^*(z))^\top c_X(z)(\nabla_x \phi_n(z) - \nabla_x \phi^*(z))p(z)dz = 0\]
\end{lem}
\begin{proof}
First we extend $\phi^*$ to all of $\R^{d+m}$ by setting $\phi^*(z) = 0$ if $z \not \in F$. Next let $(\eta_\epsilon)_{\epsilon > 0}$ be a standard mollifier on $\R^{d+m}$ and define $\phi^n = \phi^**\eta_{1/n}$. Clearly $\phi^n \in C_c^\infty(\R^{d+m})$ and so its restriction to $F_k$ belongs to $W^{1,2}(F_k)$ for every $k \in \N$. By density of $C_c^\infty(F_k)$ in $W^{1,2}(F_k)$ we can find functions $\phi^n_{j,k} \in C_c^\infty(F_k)$ such that
\begin{equation}
    \label{eqn:Fk_converge}
    \lim_{j \to \infty} \|\phi^n_{j,k} - \phi^n\|_{W^{1,2}(F_k)} = 0.
\end{equation}
Next, to simplify the exposition for any open set $U \subset F$ and function $\phi: F \to \R$ weakly differentiable in $x$ we will write
\[\|\phi\|_{\Wcal(U)} = \int_U \nabla_x \phi(z)^\top c_X(z)\nabla_x\phi(z)p(z)dz.\] Then it follows from \eqref{eqn:Fk_converge} that
\begin{align} 
\lim_{j \to \infty} \|\phi^n_{k,j} - \phi^n\|_{\Wcal(F_k)} \leq \sup_{z \in F_k}\lambda_{\max}(c_X(z))p(z)\lim_{j \to \infty}\|\nabla_x\phi^n_{j,k}-\nabla_x\phi^n\|_{L^2(F_k;\R^d)} = 0.

\end{align}  Next, note that because $\phi^*$ is itself continuously differentiable in $x$, with $\nabla_x\phi^* \in L^2(F_k;\R^d)$ courtesy of Lemma~\ref{lem:variational_technical}, we have for every $i=1,\dots,d$ that $\partial_{x_i} \phi^n = (\partial_{x_i}\phi^*)* \eta_{1/n}$, which by standard properties of mollification (see e.g. \cite[Theorem~~C.5.7]{evanspartial2010}) converges to $\partial_{x_i}\phi^*$ as $n \to \infty$ in $L^2(F_k)$. It then follows, again using uniform boundedness of $c_Xp$ on $F_k$, that
$\lim_{n \to \infty}\|\phi^n - \phi^*\|_{\Wcal(F_k)} = 0.$
Finally, note by monotone convergence, that $\lim_{k \to \infty} \|\phi^*\|_{\Wcal(F\setminus F_k)} = 0$. As such given a tolerance $\epsilon > 0$ we first choose $k$, then $n = n(k)$ and then $j = j(n,k)$ large enough so that
\[\|\phi^*\|_{\Wcal(F\setminus F_k)} < \frac{\epsilon}{3}, \qquad \|\phi^* - \phi^n\|_{\Wcal(F_k)} < \frac{\epsilon}{3}, \qquad \|\phi^n - \phi^n_{j,k}\|_{\Wcal(F_k)} < \frac{\epsilon}{3}.\]
Then we see by the triangle inequality that
\begin{align}
\|\phi^* - \phi^n_{j,k}\|_{\Wcal(F)} & = \|\phi^*\|_{\Wcal(F\setminus F_k)} + \|\phi^* - \phi^n_{j,k}\|_{\Wcal(F_k)} \\
& \leq \|\phi^*\|_{\Wcal(F\setminus F_k)} + \|\phi^* - \phi^n\|_{\Wcal(F_k)} + \|\phi^n -  \phi^n_{j,k}\|_{\Wcal(F_k)} < \epsilon.
\end{align}
Since each $\phi^n_{j,k} \in C_c^\infty(F)$ this completes the proof.
\end{proof}


















































































\begin{proof}[Proof of Theorem~\ref{thm:main}] We set $\theta^n_t = \nabla_x \phi_n(Z_t)$, where $\phi_n$ is as in Lemma~\ref{lem:approx}. Since $\phi_n \in C_c^\infty(F)$ we can apply It\^o's formula and the steps in Section~\ref{sec:heuristic} to obtain for any $\P \in \Pcal$ that
\begin{align}
    g(\theta^n;\P) & = \frac{1}{2}\int_F \xi(z)^\top c_X(z)\xi(z)p(z)dz - \frac{1}{2}\int_F (\nabla_x \phi_n(z)-\xi(z))^\top c_X(z)(\nabla_x \phi_n(z) - \xi(z))p(z)dz \\
    & = \int_F \nabla_x\phi_n(z)^\top c_X(z)\xi(z)p(z)dz - \frac{1}{2}\int_F \nabla_x\phi_n(z)^\top c_X(z)\nabla_x \phi_n(z)p(z)dz \\
    & = \int_F \nabla_x\phi_n(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz - \frac{1}{2}\int_F \nabla_x\phi_n(z)^\top c_X(z)\nabla_x \phi_n(z)p(z)dz,
\end{align} 
where in the final equality we used that $\phi^*$ is a weak solution to the Euler-Lagrange equation \eqref{eqn:Euler-Lagrange_xi}. This leads us to the lower bound
\begin{align} 
\lambda_{\Pcal} \geq \lim_{n \to \infty} \inf_{\P \in \Pcal} g(\theta^n;\P) = \frac{1}{2}\int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz,
\end{align}
where we used Lemma~\ref{lem:approx} to compute the limit. 

To obtain the upper bound we use the measure $\P^*$ constructed in Proposition~\ref{prop:worst_case} (with any initial value $z \in F$). As shown in the proof of Proposition~\ref{prop:worst_case}, $\theta^*$ is growth-optimal under $\P^*$ with asymptotic growth rate derived in \eqref{eqn:worst_case_growth}. Hence,
\[\lambda_{\Pcal} \leq  \sup_{\theta \in \Theta} g(\theta;\P^*) = g(\theta^*;\P^*) = \frac{1}{2}\int_F \nabla_x \phi^*(z)^\top c_X(z)\nabla_x \phi^*(z)p(z)dz.\]
This establishes the robust growth rate formula so it now just remains to show that $\theta^*$ achieves this same asymptotic growth rate under every $\P \in \Pcal_0$. To this end we fix $\P \in \Pcal_0$ and note that for any $\theta \in \Theta$ we have
\[\log V^\theta_T = \int_0^T \theta_t^\top dX_t - \frac{1}{2}\int_0^T \theta_t^\top c(Z_t)\theta_t dt.\] Now taking $\theta^*$ and $\theta_n$ from the first part of this proof we see that
\begin{align} \log V_T^{\theta^*} = \log V_T^{\theta_n}    - \frac{1}{2}\int_0^T (\nabla_x \phi^*)^\top c_X\nabla_x \phi^*(Z_t)dt & + \frac{1}{2} \int_0^T \nabla_x \phi_n^\top c_X\nabla_x  \phi_n(Z_t)dt \qquad \label{eqn:opt_wealth_easy} \\ & \qquad   + \int_0^T(\theta^*_t - \theta^n_t)^\top dX_t \label{eqn:opt_wealth_hard}.
\end{align}
We now divide by $T$ and send $T \to \infty$ and then $n \to \infty$. The growth rate invariance property of $\theta_n$ together with the ergodic property \eqref{eqn:ergodic} and Lemma~\ref{lem:approx} shows that the terms on the right hand side of \eqref{eqn:opt_wealth_easy} converge $\P$-a.s.\ to $\lambda_{\Pcal}$. To complete the proof it suffices to show that
\begin{equation} \label{eqn:stoch_int_growth}
  \lim_{n \to \infty}\sup\Big\{\gamma \in \R: \liminf_{T \to \infty} \frac{1}{T}\int_0^T(\theta^*_t - \theta_t^n)^\top dX_t\geq \gamma \Big\} = 0.
\end{equation}
To this end we recall the dynamics of $X$ under $\P$, which leads us to the estimates
\begin{equation} \label{eqn:stoch_int_bound}
\left|\frac{1}{T}\int_0^T (\theta^*_t - \theta^n_t)^\top dX_t\right| \leq\left|\frac{1}{T}\int_0^T (\nabla_x\phi^*(Z_t)-\nabla_x \phi_n(Z_t))^\top c_X(Z_t) b^\P_{X,t}dt\right| +\frac{1}{T}|L^n_T|, 
\end{equation}
where $L^n_T := \sum_{i=1}^d\sum_{j=1}^{d+m}\int_0^T (\partial_i\phi^*(Z_t)-\partial_i \phi_n(Z_t)) c^{1/2}_{ij}(Z_t)dW_{j,t}$ is a local martingale. We have that 
\[\lim_{T \to \infty}\frac{1}{T}[L^n]_T = \int_F (\nabla_x \phi^*(z) - \nabla_x \phi_n(z))^\top c_x(z)(\nabla_x \phi^*(z) -\nabla_x \phi_n(z))p(z)dz < \infty,\]
so by \cite[Lemma~1.3.2]{fernholz2002stochastic}, $\lim_{T \to \infty} \frac{1}{T}L^n_T = 0$. For the drift term we use Cauchy--Schwarz to obtain
\begin{align}\bigg|\frac{1}{T}\int_0^T & (\nabla_x\phi^*(Z_t)-\nabla_x \phi_n(Z_t))^\top c_X(Z_t) b^\P_{X,t})dt\bigg| \\&  \leq \left(\frac{1}{T}\int_0^T(\nabla_x \phi^* - \nabla_x \phi_n)^\top c_X(\nabla_x \phi^*-\nabla_x \phi_n)(Z_t)dt\right)^{\frac{1}{2}} \left(\frac{1}{T}\int_0^T (b_{X,t}^\P)^\top c_X(Z_t)b_{X,t}^\P dt\right)^{\frac{1}{2}} \label{eqn:Pcal0_estimate}.
\end{align}
By the ergodic property \eqref{eqn:ergodic} and Lemma~\ref{lem:approx} we have that the first term on the right hand side of \eqref{eqn:Pcal0_estimate} tends $\P$-a.s.\ to zero as $T$ and then $n$ goes to infinity. The condition \eqref{eqn:bP_condition}, which holds here since $\P \in \Pcal_0$, ensures that the second term in \eqref{eqn:Pcal0_estimate} remains finite on a set of strictly positive measure when sending $T \to \infty$. This establishes \eqref{eqn:stoch_int_growth} and completes the proof. 
\end{proof}

